import math


def fib(n: int):
    if n <= 0:
        raise ValueError("Input must be a positive integer")
    elif n == 1:
        return 0
    elif n == 2:
        return 1
    else:
        # Calculate the n-th Fibonacci number using matrix exponentiation for efficiency
        F = [[1, 1], [1, 0]]
        power = mat_power(F, n - 1)
        return power[0][0]


def mat_power(F, n):
    if n == 1:
        return F
    else:
        # Use the property of Fibonacci Matrix ([[1, 1], [1, 0]]), F^n = (F^(n/2))^2 for even n and F^n = F * F^(n//2+1) for odd n
        half_power = mat_power(F, n // 2)

        if n % 2 == 0:
            return matrix_multiply(half_power, half_power)
        else:
            return matrix_multiply(F, mat_power(F, n // 2 + 1))


def matrix_multiply(mat1, mat2):
    result = [[0, 0], [0, 0]]
    for i in range(len(mat1)):
        for j in range(len(mat2[0])):
            for k in range(len(mat2)):
                result[i][j] += mat1[i][k] * mat2[k][j]
    return result


# Test the function with example uses
if __name__ == "__main__":
    # Test cases
    print(fib(10))
    print(fib(1))
    print(fib(8))
