import math


def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Check for even number and divide until only an odd number is left
    while n % 2 == 0:
        n = n // 2

    factor = 3
    while factor <= math.sqrt(n):
        # While factor divides n, divide n
        while n % factor == 0:
            n = n // factor
        if n == 1:
            return factor
        factor += 2

    # If n is a prime number
    return n


