import heapq


def move_one_ball(arr):
    """Determine if an array can be sorted in non-decreasing order by performing
    right shift operations.

    Args:
        arr ([int]): A list of integers.

    Returns:
        bool: True if it is possible to get a sorted array, False otherwise.
    """

    if not arr:
        return True

    def is_sorted(arr):
        """Check if the given array is sorted in non-decreasing order."""
        return all(arr[i] <= arr[i + 1] for i in range(len(arr) - 1))

    min_heap = arr.copy()
    heapq.heapify(min_heap)

    while len(min_heap) > 1:
        if is_sorted(min_heap):
            return True
        heapq.heappop(min_heap)

    return is_sorted(min_heap)
