import collections


def histogram(test):
    """
    Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    :param test: A string of lowercase letters separated by a space
    :return: Dictionary with letters as keys and their corresponding count as values.
    """

    if not test:
        return {}

    letter_count = {}

    words = test.split()

    for word in words:
        if word:
            for letter in word:
                letter_count[letter] = letter_count.get(letter, 0) + 1

    max_count = max(letter_count.values())

    # Return a dictionary of letters with the most repetition and their corresponding count
    return {k: v for k, v in letter_count.items() if v == max_count}

