import re


def compare_one(a, b):
    if isinstance(a, str) and isinstance(b, str):
        # Check for comma as decimal point indicator
        pattern = r"(\d+[,\.]*)+\d+"
        # Check if both represent the same real number ignoring decimal points
        if re.match(pattern, a.replace(',', '.')) and re.match(pattern, b.replace(',', '.')):
            if '.' in a:
                a, b = a.split('.'), b.split('.')
                if len(a) == len(b) and all(a) == all(map(int, b)):
                    return b[0]
            else:
                a, b = a.split(','), b.split(',')
                if len(a) == len(b) and all(a) == all(map(float, b)):
                    return ','.join(map(str, max(a, b, key=float)) if a != b else b[0])
    # Convert strings to floats if both are strings
    elif isinstance(a, str) and isinstance(b, str):
        a, b = float(a.replace(',', '.')), float(b.replace(',', '.'))
    # Convert strings to numbers if possible
    else:
        try:
            a, b = float(a), float(b)
        except ValueError:
            # In case conversion fails (not numeric)
            pass

    # Return None if the values are equal
    if a == b:
        return None

    # Return the larger variable
    return max(a, b)

